package br.edu.ifms.robotica.servlet;
import java.io.IOException;import java.sql.Date;import java.sql.SQLException;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import br.edu.ifms.robotica.dao.*;import br.edu.ifms.robotica.model.Conquista;
@WebServlet("/admin/conquistas") public class ConquistaServlet extends HttpServlet{private final ConquistaDAO dao=new ConquistaDAO();private final AtividadeDAO atividadeDAO=new AtividadeDAO();
 @Override protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{try{r.setAttribute("conquistas",dao.listar());r.setAttribute("atividades",atividadeDAO.listar());r.getRequestDispatcher("/WEB-INF/views/admin/conquistas.jsp").forward(r,p);}catch(SQLException e){throw new ServletException(e);}}
 @Override protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setCharacterEncoding("UTF-8");try{String a=r.getParameter("acao");if("excluir".equals(a)){dao.excluir(Long.valueOf(r.getParameter("id")));redir(r,p,"exclusao");return;}Conquista c=new Conquista();if("editar".equals(a))c.setId(Long.valueOf(r.getParameter("id")));c.setAtividadeId(Long.valueOf(r.getParameter("atividadeId")));if(atividadeDAO.buscarPorId(c.getAtividadeId())==null)throw new IllegalArgumentException("erro.atividade.inexistente");c.setTitulo(r.getParameter("titulo").trim());if(c.getTitulo().isBlank())throw new IllegalArgumentException("erro.campo.obrigatorio");String data=r.getParameter("data");if(data!=null&&!data.isBlank())c.setData(Date.valueOf(data));c.setDescricao(r.getParameter("descricao"));if("editar".equals(a))dao.atualizar(c);else dao.inserir(c);redir(r,p,"editar".equals(a)?"alteracao":"cadastro");}catch(IllegalArgumentException e){r.setAttribute("erro",e.getMessage());doGet(r,p);}catch(SQLException e){throw new ServletException(e);}}
 private void redir(HttpServletRequest r,HttpServletResponse p,String s)throws IOException{p.sendRedirect(r.getContextPath()+"/admin/conquistas?sucesso="+s);}}
